package com.orcaphone.core.orca

import java.io.InputStream
import java.util.zip.GZIPInputStream

/**
 * OrcaSlicer's system presets with inheritance already resolved (generated by tools/gen_orca_catalog.py).
 * Values are raw strings as they appear in OrcaSlicer's profile JSON (not C-escaped).
 */
class OrcaCatalog(private val data: Map<String, Map<String, Map<String, String>>>) {

    fun get(kind: OrcaKind, name: String): Map<String, String>? = data[kind.iot]?.get(name)

    fun names(kind: OrcaKind): Collection<String> = data[kind.iot]?.keys ?: emptyList()

    fun entries(kind: OrcaKind): Map<String, Map<String, String>> = data[kind.iot] ?: emptyMap()

    companion object {
        const val RESOURCE = "/orca/system_presets.json.gz"

        fun load(): OrcaCatalog {
            val stream = OrcaCatalog::class.java.getResourceAsStream(RESOURCE)
                ?: error("OrcaSlicer preset catalog missing from the app")
            return load(stream)
        }

        fun load(gz: InputStream): OrcaCatalog {
            val text = GZIPInputStream(gz).use { it.readBytes() }.toString(Charsets.UTF_8)
            @Suppress("UNCHECKED_CAST")
            return OrcaCatalog(MiniJson(text).parse() as Map<String, Map<String, Map<String, String>>>)
        }
    }
}

/**
 * Tiny JSON reader for the catalog (objects and strings only, plus scalars read as strings).
 * Interns repeated values: many printers share identical start G-code.
 */
internal class MiniJson(private val s: String) {
    private var i = 0
    private val pool = HashMap<String, String>()

    fun parse(): Any? = value().also { ws() }

    private fun ws() { while (i < s.length && s[i].isWhitespace()) i++ }

    private fun value(): Any? {
        ws()
        return when (s[i]) {
            '{' -> obj()
            '[' -> arr()
            '"' -> str()
            else -> scalar()
        }
    }

    private fun obj(): Map<String, Any?> {
        val m = LinkedHashMap<String, Any?>()
        i++
        ws()
        if (s[i] == '}') { i++; return m }
        while (true) {
            ws()
            val k = str()
            ws(); i++ // ':'
            m[k] = value()
            ws()
            if (s[i] == ',') { i++; continue }
            i++ // '}'
            return m
        }
    }

    private fun arr(): List<Any?> {
        val l = ArrayList<Any?>()
        i++
        ws()
        if (s[i] == ']') { i++; return l }
        while (true) {
            l.add(value())
            ws()
            if (s[i] == ',') { i++; continue }
            i++
            return l
        }
    }

    private fun scalar(): String {
        val start = i
        while (i < s.length && s[i] != ',' && s[i] != '}' && s[i] != ']' && !s[i].isWhitespace()) i++
        return s.substring(start, i)
    }

    private fun str(): String {
        i++ // opening quote
        val sb = StringBuilder()
        while (true) {
            val c = s[i++]
            when (c) {
                '"' -> break
                '\\' -> {
                    when (val e = s[i++]) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        'b' -> sb.append('\b')
                        'f' -> sb.append('\u000C')
                        'u' -> { sb.append(s.substring(i, i + 4).toInt(16).toChar()); i += 4 }
                        else -> sb.append(e)
                    }
                }
                else -> sb.append(c)
            }
        }
        val v = sb.toString()
        return pool.getOrPut(v) { v }
    }
}
